CREATE TABLE admin_users (
  id BIGSERIAL PRIMARY KEY,
  username VARCHAR(100) NOT NULL UNIQUE CHECK (length(trim(username)) > 0),
  password_hash TEXT NOT NULL,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);

-- To create an admin with a correctly hashed password, run:
-- npm run admin:create -- admin
-- The command prompts for the password and executes this INSERT.
-- For manual insertion, replace the placeholder with a hash generated by
-- src/modules/admin/password.js (hashPassword). Do not use a plain password.
